from lib import *
PAGE = page('trust-accessibility',
 ("Accessibility statement", "Déclaration d’accessibilité", "بيان إمكانية الوصول"),
 ("What W5D does so that everyone can read and use the site, what is not yet fully accessible, and how to report a barrier.",
  "Ce que fait W5D pour que chacun puisse lire et utiliser le site, ce qui n’est pas encore pleinement accessible, et comment signaler un obstacle.",
  "ما تفعله W5D ليتمكن الجميع من قراءة الموقع واستخدامه، وما لم يصبح بعدُ متاحًا بالكامل، وكيف تبلّغ عن عائق."),
 [
 hero('ac-hero', ("Built to be **usable by everyone.**", "Conçu pour être **utilisable par tous.**", "مصمَّم ليكون **قابلًا للاستخدام للجميع.**"),
  ("We aim for the WCAG 2.2 level AA standard in three languages, left-to-right and right-to-left. This page says what is in place, what is not, and how to tell us when we fall short.",
   "Nous visons la norme WCAG 2.2 niveau AA en trois langues, de gauche à droite et de droite à gauche. Cette page dit ce qui est en place, ce qui ne l’est pas, et comment nous signaler un manquement.",
   "نستهدف معيار WCAG 2.2 المستوى AA بثلاث لغات، من اليسار إلى اليمين ومن اليمين إلى اليسار. وتبيّن هذه الصفحة ما هو قائم وما ليس قائمًا وكيف تخبرنا حين نقصّر."),
  ("Accessibility", "Accessibilité", "إمكانية الوصول"),
  [(("Report a barrier", "Signaler un obstacle", "أبلغ عن عائق"), '/trust/corrections/', 'peak', True)]),
 prose('ac-commit', ("Our commitment, and its honest limits", "Notre engagement et ses limites honnêtes", "التزامنا وحدوده الصادقة"), [
  ("Training, certification and evidence are for people from many backgrounds: students, self-taught developers, people who use screen readers, people who cannot use a mouse, people reading on a slow phone in a shared connection, and people who read Arabic from right to left. A site that asks for trust has to be readable by all of them. We therefore treat accessibility as part of quality, not as a favour, and we test it as we test prices and links.",
   "La formation, la certification et les preuves s’adressent à des personnes d’horizons très divers : étudiants, autodidactes, utilisateurs de lecteurs d’écran, personnes qui ne peuvent pas utiliser une souris, personnes qui lisent sur un téléphone lent avec une connexion partagée, et personnes qui lisent l’arabe de droite à gauche. Un site qui demande la confiance doit être lisible par tous. Nous traitons donc l’accessibilité comme une part de la qualité, non comme une faveur, et nous la testons comme nous testons les prix et les liens.",
   "التدريب والاعتماد والأدلة موجهة إلى أشخاص من خلفيات كثيرة: طلاب ومطورون متعلمون ذاتيًا ومستخدمو قارئات الشاشة وأشخاص لا يستطيعون استخدام الفأرة وأشخاص يقرؤون على هاتف بطيء بإنترنت مشترك وأشخاص يقرؤون العربية من اليمين إلى اليسار. والموقع الذي يطلب الثقة يجب أن يكون مقروءًا للجميع. لذلك نعدّ إمكانية الوصول جزءًا من الجودة لا منّة، ونختبرها كما نختبر الأسعار والروابط."),
  ("The target is WCAG 2.2 level AA. “Target” is the exact word: we have not been audited by an independent accessibility body, and we do not claim full conformance. What we can tell you is what the code does, which is listed below, and what we know it does not do yet, which is listed further down. When an independent audit is carried out, its date and result will be added to this page and not hidden.",
   "L’objectif est WCAG 2.2 niveau AA. « Objectif » est le mot exact : nous n’avons pas été audités par un organisme indépendant d’accessibilité et nous ne revendiquons pas une conformité totale. Ce que nous pouvons dire, c’est ce que fait le code, listé ci-dessous, et ce que nous savons qu’il ne fait pas encore, listé plus bas. Lorsqu’un audit indépendant sera réalisé, sa date et son résultat seront ajoutés à cette page et non dissimulés.",
   "الهدف هو WCAG 2.2 المستوى AA. و«الهدف» هو اللفظ الدقيق: لم تدقق في موقعنا جهة مستقلة لإمكانية الوصول، ولا ندّعي مطابقة كاملة. ما نستطيع قوله هو ما تفعله الشيفرة وهو مذكور أدناه، وما نعلم أنها لا تفعله بعد وهو مذكور لاحقًا. وحين يُجرى تدقيق مستقل ستُضاف تاريخه ونتيجته إلى هذه الصفحة ولن تُخفى.")]),
 defs('ac-inplace', ("What is in place today", "Ce qui est en place aujourd’hui", "ما هو قائم اليوم"), [
  (("Skip link", "Lien d’évitement", "رابط التخطي"), ("The first focusable element on every page is a link that jumps straight to the main content, so that a keyboard or screen-reader user does not have to pass the whole menu on every page.", "Le premier élément focalisable de chaque page est un lien qui mène directement au contenu principal, afin qu’un utilisateur du clavier ou d’un lecteur d’écran n’ait pas à traverser tout le menu à chaque page.", "أول عنصر قابل للتركيز في كل صفحة رابط ينقل مباشرة إلى المحتوى الرئيسي، فلا يضطر مستخدم لوحة المفاتيح أو قارئ الشاشة إلى المرور بكل القائمة في كل صفحة.")),
  (("Visible keyboard focus", "Focus clavier visible", "تركيز لوحة المفاتيح مرئي"), ("Buttons, links, fields and summaries show a clear ring when reached with the keyboard. It is drawn by the style sheet for every interactive element, not left to the browser default.", "Boutons, liens, champs et résumés affichent un anneau net lorsqu’ils sont atteints au clavier. Il est dessiné par la feuille de style pour chaque élément interactif, sans dépendre du comportement par défaut du navigateur.", "تُظهر الأزرار والروابط والحقول والملخصات حلقة واضحة عند بلوغها بلوحة المفاتيح. وترسمها ورقة الأنماط لكل عنصر تفاعلي ولا تُترك للسلوك الافتراضي للمتصفح.")),
  (("Language and direction", "Langue et direction", "اللغة والاتجاه"), ("Each page declares its language and its writing direction. Arabic pages are laid out right-to-left with their own style rules, not mirrored by hand, and the switch between English, French and Arabic is available on every page.", "Chaque page déclare sa langue et son sens d’écriture. Les pages arabes sont mises en page de droite à gauche avec leurs propres règles de style, sans miroir manuel, et le changement entre anglais, français et arabe est disponible sur chaque page.", "تعلن كل صفحة لغتها واتجاه كتابتها. وتُنسَّق الصفحات العربية من اليمين إلى اليسار بقواعد أنماط خاصة لا بقلب يدوي، ويتوفر التبديل بين الإنجليزية والفرنسية والعربية في كل صفحة.")),
  (("One main heading per page", "Un seul titre principal par page", "عنوان رئيسي واحد في كل صفحة"), ("Every page has one top-level heading followed by section headings in order, so that a screen-reader user can list the headings and move between sections.", "Chaque page a un titre de premier niveau suivi de titres de section dans l’ordre, de sorte qu’un utilisateur de lecteur d’écran puisse lister les titres et passer d’une section à l’autre.", "لكل صفحة عنوان أعلى واحد تتبعه عناوين الأقسام بترتيبها، فيستطيع مستخدم قارئ الشاشة سرد العناوين والتنقل بين الأقسام.")),
  (("Labelled forms", "Formulaires étiquetés", "نماذج موسومة"), ("Form fields have visible labels, errors are written in words and are not shown by colour alone, and every form works without a mouse.", "Les champs de formulaire ont des libellés visibles, les erreurs sont écrites en toutes lettres et ne reposent pas sur la seule couleur, et chaque formulaire fonctionne sans souris.", "لحقول النماذج وسوم ظاهرة، وتُكتب الأخطاء بالكلمات ولا تعتمد على اللون وحده، ويعمل كل نموذج بلا فأرة.")),
  (("Light and dark themes", "Thèmes clair et sombre", "السمتان الفاتحة والداكنة"), ("You can switch the colour theme at any time and the choice is remembered on your device. Text colours are chosen to keep a readable contrast in both themes.", "Vous pouvez changer le thème de couleurs à tout moment et le choix est mémorisé sur votre appareil. Les couleurs de texte sont choisies pour conserver un contraste lisible dans les deux thèmes.", "يمكنك تبديل سمة الألوان في أي وقت ويُحفظ اختيارك على جهازك. وتُختار ألوان النص للحفاظ على تباين مقروء في السمتين.")),
  (("Works without a script for reading", "Lecture possible sans script", "القراءة ممكنة بلا سكربت"), ("Articles, tables, prices and trust pages are plain HTML. Scripts add comfort (menus, counters, the cookie notice); they are not needed to read the content.", "Articles, tableaux, prix et pages de confiance sont du HTML simple. Les scripts ajoutent du confort (menus, compteurs, avis cookies) ; ils ne sont pas nécessaires pour lire le contenu.", "المقالات والجداول والأسعار وصفحات الثقة HTML بسيط. وتضيف السكربتات راحة (القوائم والعدادات وإشعار الكوكيز) ولا حاجة إليها لقراءة المحتوى."))]),
 prose('ac-motion', ("Animation and your control over it", "L’animation et votre contrôle sur elle", "الحركة وتحكمك فيها"), [
  ("The site uses motion on cards, counters and reveals. It runs automatically, without a click. We chose not to read your operating system’s “reduce motion” flag as a silent switch, because many desktops report that flag without the owner knowing, and the site then looked static to people who wanted to see it. The consequence is important and we state it plainly: if you are sensitive to motion, the site will not detect that for you. You have to turn it off yourself.",
   "Le site utilise du mouvement sur les cartes, compteurs et apparitions. Il s’exécute automatiquement, sans clic. Nous avons choisi de ne pas lire l’indicateur « réduire les animations » de votre système comme un interrupteur silencieux, car de nombreux ordinateurs le signalent à l’insu de leur propriétaire, et le site paraissait alors figé à des personnes qui voulaient le voir. La conséquence est importante et nous la disons clairement : si vous êtes sensible au mouvement, le site ne le détectera pas pour vous. Vous devez le désactiver vous-même.",
   "يستخدم الموقع الحركة في البطاقات والعدادات والظهور التدريجي، وتعمل تلقائيًا بلا نقرة. اخترنا ألا نقرأ علم «تقليل الحركة» في نظام تشغيلك كمفتاح صامت، لأن كثيرًا من الحواسيب تُبلغ عنه دون علم صاحبها فيبدو الموقع ساكنًا لمن أراد رؤيته. والنتيجة مهمة ونذكرها بوضوح: إذا كنت حساسًا للحركة فلن يكتشف الموقع ذلك عنك، وعليك أن توقفها بنفسك."),
  ("There is a “Reduce animations” control in the footer and in the cookie settings. It stops decorative motion on every page at once and the choice is remembered on your device, in the key `w5d-motion`. Pressing it again restores the animations. We consider this an acceptable design for decorative motion, and we list it among our known limits below, because a reader might reasonably expect the system flag to be honoured as well.",
   "Un contrôle « Réduire les animations » existe dans le pied de page et dans les réglages des cookies. Il arrête le mouvement décoratif sur toutes les pages à la fois et le choix est mémorisé sur votre appareil, dans la clé `w5d-motion`. Un nouvel appui rétablit les animations. Nous jugeons ce dispositif acceptable pour du mouvement décoratif, et nous le listons parmi nos limites connues plus bas, car un lecteur pourrait raisonnablement s’attendre à ce que l’indicateur du système soit aussi respecté.",
   "يوجد زر «تقليل الحركة» في التذييل وفي إعدادات الكوكيز. فهو يوقف الحركة الزخرفية في كل الصفحات دفعة واحدة ويُحفظ اختيارك على جهازك في المفتاح `w5d-motion`، ويعيد الضغط عليه الحركة. ونرى هذا تصميمًا مقبولًا للحركة الزخرفية، ونذكره بين حدودنا المعروفة أدناه، لأن القارئ قد يتوقع بحق احترام علم النظام أيضًا.")]),
 table('ac-limits', ("Known limits, and what we do about them", "Limites connues et ce que nous en faisons", "الحدود المعروفة وما نفعله بشأنها"),
  [("Known limit", "Limite connue", "الحد المعروف"), ("Effect", "Effet", "الأثر"), ("Plan", "Plan", "الخطة")],
  [[("Motion is switched off by the visitor, not detected from the system", "Le mouvement est désactivé par le visiteur, non détecté depuis le système", "الحركة يوقفها الزائر ولا تُكتشف من النظام"), ("People who are sensitive to motion must find the control themselves.", "Les personnes sensibles au mouvement doivent trouver elles-mêmes le contrôle.", "على الحساسين للحركة أن يجدوا الزر بأنفسهم."), ("Keep the control in the footer and cookie settings; review the default at each audit.", "Garder le contrôle dans le pied de page et les réglages des cookies ; réexaminer le défaut à chaque audit.", "إبقاء الزر في التذييل وإعدادات الكوكيز ومراجعة الافتراضي عند كل تدقيق.")],
   [("No independent audit yet", "Pas encore d’audit indépendant", "لا تدقيق مستقل بعد"), ("Conformance to WCAG 2.2 AA is a target, not a certified fact.", "La conformité WCAG 2.2 AA est un objectif, non un fait certifié.", "المطابقة لـ WCAG 2.2 AA هدف لا حقيقة معتمدة."), ("Commission an audit once the programme has funds, and publish the result with its date.", "Commander un audit lorsque le programme disposera de fonds et publier le résultat avec sa date.", "تكليف تدقيق حين يتوفر تمويل للبرنامج ونشر النتيجة بتاريخها.")],
   [("Some generated service pages are long", "Certaines pages de services générées sont longues", "بعض صفحات الخدمات المولدة طويلة"), ("Long pages are harder for people who use screen magnifiers or voice control.", "Les pages longues sont plus difficiles pour ceux qui utilisent une loupe d’écran ou la commande vocale.", "الصفحات الطويلة أصعب على مستخدمي مكبّر الشاشة أو الأوامر الصوتية."), ("Keep section headings and anchors consistent; add a table of contents where a page is long.", "Garder des titres de section et des ancres cohérents ; ajouter une table des matières quand une page est longue.", "إبقاء عناوين الأقسام والمراسي متسقة وإضافة فهرس حيث تطول الصفحة.")],
   [("Third-party reCAPTCHA, when enabled", "reCAPTCHA tiers, lorsqu’il est activé", "reCAPTCHA من طرف ثالث عند تفعيله"), ("A visual challenge can be a barrier for some people.", "Un défi visuel peut être un obstacle pour certaines personnes.", "قد يكون التحدي البصري عائقًا لبعضهم."), ("Anyone blocked can use the e-mail address on the imprint page, which has no challenge.", "Toute personne bloquée peut utiliser l’adresse e-mail de la page des mentions légales, qui n’a aucun défi.", "يستطيع من أُعيق استخدام البريد المذكور في صفحة الإشعار القانوني ولا تحدٍّ فيه.")],
   [("Arabic and French text written by hand, not yet reviewed by native accessibility testers", "Texte arabe et français écrit à la main, pas encore relu par des testeurs d’accessibilité natifs", "نص عربي وفرنسي مكتوب يدويًا ولم يراجعه بعدُ مختبرون أصليون لإمكانية الوصول"), ("Wording can be clumsy for a screen reader reading aloud.", "La formulation peut être maladroite pour un lecteur d’écran qui lit à voix haute.", "قد تكون الصياغة ثقيلة على قارئ شاشة يقرأ بصوت عالٍ."), ("Invite reviews through the corrections desk and correct within {{ quality.correction_sla_days }} days.", "Inviter des relectures via le service des corrections et corriger sous {{ quality.correction_sla_days }} jours.", "دعوة المراجعات عبر مكتب التصويبات والتصحيح خلال {{ quality.correction_sla_days }} يومًا.")]],
  note=("We would rather publish a limit than hide it. A limit that is written down can be fixed and can be held against us.",
        "Nous préférons publier une limite que la cacher. Une limite écrite peut être corrigée et peut nous être opposée.",
        "نفضّل نشر الحد على إخفائه. فالحد المكتوب يمكن إصلاحه ويمكن أن يُحتجّ به علينا.")),
 steps('ac-howtest', ("How we check", "Comment nous vérifions", "كيف نتحقق"), [
  (("Automated checks on every release", "Contrôles automatiques à chaque version", "فحوص آلية عند كل إصدار"), ("A crawler script visits every page in all three languages and looks for pages without a language, empty links, images without a text alternative, forms without labels and pages with more than one main heading. The team runs it before a release; it is not yet a blocking step of the automated release script, and we say so rather than imply it is.", "Un script d’exploration visite chaque page dans les trois langues et recherche les pages sans langue, les liens vides, les images sans alternative textuelle, les formulaires sans libellés et les pages avec plus d’un titre principal. L’équipe l’exécute avant une version ; ce n’est pas encore une étape bloquante du script de livraison automatisé, et nous le disons plutôt que de le laisser croire.", "يزور سكربت زاحف كل صفحة بلغاتها الثلاث ويبحث عن صفحات بلا لغة وروابط فارغة وصور بلا بديل نصي ونماذج بلا وسوم وصفحات فيها أكثر من عنوان رئيسي. ويشغّله الفريق قبل كل إصدار؛ وهو ليس بعدُ خطوة مانعة في سكربت الإصدار الآلي، ونقول ذلك بدل أن نوحي بغيره.")),
  (("Keyboard walk-through", "Parcours au clavier", "جولة بلوحة المفاتيح"), ("Before each major change to the template, someone goes through the main journeys with the keyboard only: menu, language switch, forms, cookie notice, checkout.", "Avant chaque changement majeur du gabarit, quelqu’un parcourt les principaux parcours au clavier seul : menu, changement de langue, formulaires, avis cookies, paiement.", "قبل كل تغيير كبير في القالب يجتاز شخص المسارات الرئيسية بلوحة المفاتيح وحدها: القائمة وتبديل اللغة والنماذج وإشعار الكوكيز والدفع.")),
  (("Screen-reader and zoom spot checks", "Contrôles ponctuels au lecteur d’écran et au zoom", "فحوص انتقائية بقارئ الشاشة والتكبير"), ("We read key pages with a screen reader in each language and at 200% zoom. These are spot checks by the team, not a replacement for an audit by disabled users.", "Nous lisons les pages clés avec un lecteur d’écran dans chaque langue et à 200 % de zoom. Ce sont des contrôles ponctuels de l’équipe, non un remplacement de l’audit par des utilisateurs en situation de handicap.", "نقرأ الصفحات الرئيسية بقارئ شاشة في كل لغة وبتكبير 200%. وهي فحوص انتقائية من الفريق لا تغني عن تدقيق يجريه مستخدمون من ذوي الإعاقة.")),
  (("Reports from readers", "Signalements des lecteurs", "بلاغات القراء"), ("A report is the most reliable test. It is logged, answered within {{ company.response_days }} working days and, if the barrier is real, fixed and noted on the [corrections page](/trust/corrections/).", "Un signalement est le test le plus fiable. Il est consigné, reçoit une réponse sous {{ company.response_days }} jours ouvrés et, si l’obstacle est réel, il est corrigé et noté sur la [page des corrections](/trust/corrections/).", "البلاغ أوثق اختبار. يُسجَّل ويُجاب عنه خلال {{ company.response_days }} أيام عمل، وإن كان العائق حقيقيًا يُصلَح ويُدوَّن في [صفحة التصويبات](/trust/corrections/).")),
  (("Review of this statement", "Révision de cette déclaration", "مراجعة هذا البيان"), ("The statement is re-read whenever the template changes in a way that affects navigation, colour or forms, and at least every {{ legal.review_months }} months.", "La déclaration est relue chaque fois que le gabarit change d’une façon qui touche la navigation, les couleurs ou les formulaires, et au moins tous les {{ legal.review_months }} mois.", "يُعاد قراءة البيان كلما تغير القالب بما يمس التنقل أو الألوان أو النماذج، وكل {{ legal.review_months }} أشهر على الأقل."))]),
 prose('ac-law', ("The legal frame, in Tunisia and elsewhere", "Le cadre juridique, en Tunisie et ailleurs", "الإطار القانوني في تونس وخارجها"), [
  ("Tunisian law protects the rights of persons with disabilities, including access to information and services, and sets a general direction that public and private services should be reachable by everyone. We follow that direction by choice, with the international WCAG standard as the technical yardstick, because it is the one tool that readers, testers and developers in every country already share. We do not claim to know how each Tunisian rule applies to a private training platform, and this is one of the points confirmed with a lawyer at each review.",
   "Le droit tunisien protège les droits des personnes handicapées, notamment l’accès à l’information et aux services, et fixe une orientation générale selon laquelle les services publics et privés doivent être accessibles à tous. Nous suivons cette orientation par choix, avec la norme internationale WCAG comme référence technique, car c’est le seul outil que lecteurs, testeurs et développeurs de tous les pays partagent déjà. Nous ne prétendons pas savoir comment chaque règle tunisienne s’applique à une plateforme de formation privée, et c’est l’un des points confirmés avec un avocat à chaque revue.",
   "يحمي القانون التونسي حقوق الأشخاص ذوي الإعاقة، ومنها النفاذ إلى المعلومات والخدمات، ويضع توجهًا عامًا بأن تكون الخدمات العامة والخاصة في متناول الجميع. ونتبع هذا التوجه اختيارًا، ونتخذ معيار WCAG الدولي مقياسًا تقنيًا لأنه الأداة الوحيدة التي يتشاركها القراء والمختبرون والمطورون في كل بلد. ولا ندّعي معرفة كيف تنطبق كل قاعدة تونسية على منصة تدريب خاصة، وهذه من النقاط التي نؤكدها مع محامٍ في كل مراجعة."),
  ("For readers outside Tunisia, other regimes may apply to the services you buy, such as the European accessibility rules for products and services. These rules apply to the seller when a consumer in the Union is addressed. We state our target openly so that you can judge for yourself and, if you believe we fall short of a rule that binds us, tell us through the [contact page](/contact/) so that we can answer in writing.",
   "Pour les lecteurs hors de Tunisie, d’autres régimes peuvent s’appliquer aux services que vous achetez, comme les règles européennes d’accessibilité des produits et services. Ces règles s’appliquent au vendeur lorsqu’un consommateur de l’Union est visé. Nous énonçons notre objectif ouvertement afin que vous puissiez juger par vous-même et, si vous estimez que nous restons en deçà d’une règle qui nous lie, nous le dire via la [page de contact](/contact/) pour que nous répondions par écrit.",
   "وللقراء خارج تونس قد تنطبق أنظمة أخرى على الخدمات التي تشترونها، مثل القواعد الأوروبية لإمكانية الوصول في المنتجات والخدمات، وهي تسري على البائع حين يُخاطَب مستهلك في الاتحاد. ونعلن هدفنا صراحةً لتحكموا بأنفسكم، وإن رأيتم أننا نقصّر عن قاعدة تلزمنا فأخبرونا عبر [صفحة الاتصال](/contact/) لنجيب كتابةً.")]),
 faq('ac-faq', ("Questions about accessibility", "Questions sur l’accessibilité", "أسئلة عن إمكانية الوصول"), [
  (("Can I use the site with only a keyboard?", "Puis-je utiliser le site avec le seul clavier ?", "هل أستطيع استخدام الموقع بلوحة المفاتيح وحدها؟"), ("Yes. Use Tab to move forward, Shift and Tab to move back, Enter to follow a link and Escape to close a menu or a dialog. The first Tab on any page reveals the skip link.", "Oui. Utilisez Tab pour avancer, Maj et Tab pour reculer, Entrée pour suivre un lien et Échap pour fermer un menu ou une boîte de dialogue. Le premier appui sur Tab de chaque page révèle le lien d’évitement.", "نعم. استخدم Tab للتقدم وShift مع Tab للرجوع وEnter لفتح رابط وEscape لإغلاق قائمة أو نافذة حوار. وأول ضغطة Tab في أي صفحة تُظهر رابط التخطي.")),
  (("Is the Arabic version a mirror of the English one?", "La version arabe est-elle un miroir de l’anglaise ?", "هل النسخة العربية مجرد عكس للإنجليزية؟"), ("No. Arabic is written by hand and set with its own right-to-left rules. Numbers, code and Latin names stay left-to-right inside Arabic sentences, as a reader expects.", "Non. L’arabe est écrit à la main et composé avec ses propres règles de droite à gauche. Les nombres, le code et les noms latins restent de gauche à droite à l’intérieur des phrases arabes, comme le lecteur s’y attend.", "لا. العربية مكتوبة يدويًا ومنسَّقة بقواعدها الخاصة من اليمين إلى اليسار. وتبقى الأرقام والشيفرة والأسماء اللاتينية من اليسار إلى اليمين داخل الجمل العربية كما يتوقع القارئ.")),
  (("The page moves too much. What can I do?", "La page bouge trop. Que faire ?", "الصفحة تتحرك كثيرًا. ماذا أفعل؟"), ("Press “Reduce animations” in the footer. The page reloads without decorative motion and remembers your choice. See the section on animation above for why this is a button and not automatic.", "Appuyez sur « Réduire les animations » dans le pied de page. La page se recharge sans mouvement décoratif et mémorise votre choix. Voyez la section sur l’animation ci-dessus pour comprendre pourquoi c’est un bouton et non un automatisme.", "اضغط «تقليل الحركة» في التذييل. تُعاد تحميل الصفحة بلا حركة زخرفية وتحفظ اختيارك. وانظر قسم الحركة أعلاه لتعرف لماذا هو زر وليس تلقائيًا.")),
  (("Can I get a document in another form?", "Puis-je obtenir un document sous une autre forme ?", "هل أستطيع الحصول على وثيقة بصيغة أخرى؟"), ("Yes. Ask for a text version of any page, certificate or contract schedule through the [contact page](/contact/), and we will send a plain-text or large-print version within {{ company.response_days }} working days.", "Oui. Demandez une version texte de toute page, de tout diplôme ou de tout calendrier de contrat via la [page de contact](/contact/), et nous enverrons une version en texte brut ou en gros caractères sous {{ company.response_days }} jours ouvrés.", "نعم. اطلب نسخة نصية من أي صفحة أو شهادة أو جدول عقد عبر [صفحة الاتصال](/contact/) وسنرسل نسخة نصية عادية أو بخط كبير خلال {{ company.response_days }} أيام عمل.")),
  (("Who do I tell if I am blocked?", "À qui m’adresser si je suis bloqué ?", "من أخبر إذا أُعيقت؟"), ("Write to {{ company.privacy_contact }} or use the [corrections desk](/trust/corrections/). Say which page, what you were trying to do and, if you can, which browser or assistive technology you use.", "Écrivez à {{ company.privacy_contact }} ou utilisez le [service des corrections](/trust/corrections/). Indiquez la page, ce que vous essayiez de faire et, si possible, le navigateur ou la technologie d’assistance utilisés.", "راسل {{ company.privacy_contact }} أو استخدم [مكتب التصويبات](/trust/corrections/). اذكر الصفحة وما كنت تحاول فعله، وإن أمكن المتصفح أو التقنية المساعدة المستخدمة."))]),
 prose('ac-related', ("Related pages and review", "Pages liées et revue", "صفحات ذات صلة والمراجعة"), [
  ("Read the [editorial policy](/trust/editorial/), the [corrections page](/trust/corrections/), the [cookie policy](/trust/cookies/), the [imprint](/trust/imprint/) and the [declared limits](/trust/statement/). Every barrier we fix is noted with its date.",
   "Lisez la [politique éditoriale](/trust/editorial/), la [page des corrections](/trust/corrections/), la [politique de cookies](/trust/cookies/), les [mentions légales](/trust/imprint/) et les [limites déclarées](/trust/statement/). Chaque obstacle levé est noté avec sa date.",
   "اقرأ [السياسة التحريرية](/trust/editorial/) و[صفحة التصويبات](/trust/corrections/) و[سياسة الكوكيز](/trust/cookies/) و[الإشعار القانوني](/trust/imprint/) و[الحدود المعلنة](/trust/statement/). وكل عائق نزيله يُدوَّن بتاريخه."),
  VERIFY]),
 cta_block('ac-final', ("A barrier we missed? **Tell us.**", "Un obstacle que nous avons manqué ? **Dites-le-nous.**", "عائق فاتنا؟ **أخبرنا.**"), ("A short message is enough. We answer within {{ company.response_days }} working days.", "Un court message suffit. Nous répondons sous {{ company.response_days }} jours ouvrés.", "تكفي رسالة قصيرة. نجيب خلال {{ company.response_days }} أيام عمل."),
  [(("Report a barrier", "Signaler un obstacle", "أبلغ عن عائق"), '/trust/corrections/', 'peak', True), (("Contact", "Contact", "اتصل بنا"), '/contact/', 'ghost', False)]),
 ])
